with Recursive PostsTree as (
  select
    p.Id,
    p.PostTypeId,
    p.Title,
    p.OwnerUserId,
    p.Score,
    p.CreationDate,
    0 as Level,
    p.ParentId
  from Posts p
  where p.PostTypeId = 1

  union all

  select
    c.Id,
    c.PostTypeId,
    c.Title,
    c.OwnerUserId,
    c.Score,
    c.CreationDate,
    pt.Level + 1,
    c.ParentId
  from Posts c
  inner join PostsTree pt on c.ParentId = pt.Id
  where c.PostTypeId <> 1
),
MedalsUserRanks as (
  select
    b.UserId,
    b.Class,
    count(*) badge_count
  from Badges b
  where b.Date > current_date - interval '1 year'
  group by b.UserId, b.Class
),
